#!/usr/bin/env node
// Item card illustrations generated by QuiverAI (text → SVG), to compare with the app's own line
// drawings (src/items/arts.ts) on the dev page /dev/items/compare. Review tool only: nothing here is
// used by the app until shipped (item-arts-ship.mjs): the files land in decor-review/quiver/ (gitignored).
//
//   QUIVERAI_API_KEY=sk_live_… node scripts/item-arts-quiver.mjs                 the six default cards
//   QUIVERAI_API_KEY=… node scripts/item-arts-quiver.mjs revolver-38,lantern --force   these, again
//   QUIVERAI_API_KEY=… node scripts/item-arts-quiver.mjs all                      every catalogue card not done yet
// Then `node scripts/item-arts-ship.mjs` checks, trims and copies them into the app (src/items/pictures/).
//
// Options: --model <id> (default arrow-2) · --force (regenerate cards already there; each call costs
// credit, so existing ones are skipped by default) · --out <dir> (default decor-review/quiver).
// Test keys (sk_test_…) return a placeholder marked "SANDBOX RESULT", not a drawing: the page says so.
// Files: <out>/<catalog id>.svg, and <out>/manifest.json (prompt, model, tokens, sandbox) read by the page.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** What each card shows, in English (Quiver's prompts); keyed by catalogue id (src/items/catalog.ts). */
const SUBJECTS = {
  'revolver-38': 'a .38 revolver with a wooden grip and a fluted cylinder, pointing right',
  'pistol-45': 'a heavy .45 automatic pistol with a dark grip, pointing right',
  'derringer-41': 'a tiny over-under derringer pistol with a curved wooden grip',
  'rifle-3006': 'a bolt-action hunting rifle with a wooden stock, lying horizontally',
  'rifle-22': 'a light .22 farm rifle with a slim wooden stock, lying horizontally',
  'shotgun-12': 'a double-barrelled shotgun with a wooden stock, lying horizontally',
  knife: 'a hunting knife with a leather-wrapped handle and a brass guard, diagonal',
  club: 'a hardwood police club with a leather wrist strap, diagonal',
  hatchet: 'a small hatchet with a wooden handle and an iron head',
  'sword-cane': 'a gentleman’s walking cane with a brass knob',
  dynamite: 'three sticks of red dynamite tied together, with a lit fuse',
  'ammo-38': 'a small cardboard box of revolver cartridges, open, a few brass .38 cartridges standing beside it',
  'ammo-45': 'two loaded pistol magazines with brass .45 cartridges showing at the top',
  'ammo-41': 'a small handful of short brass .41 cartridges',
  'ammo-3006': 'a stripper clip of five long brass rifle cartridges',
  'ammo-22': 'a small paper box of tiny .22 rimfire cartridges, open',
  'ammo-12': 'two red paper shotgun shells with brass bases, standing',
  flashlight: 'an old metal flashlight casting a short beam',
  lantern: 'a hurricane oil lantern with a glass globe and a small flame, wire handle',
  candles: 'a candle in a brass candlestick with a small flame',
  matches: 'an open box of matches with two matches sticking out',
  flare: 'a red signal flare stick burning with bright sparks at its tip',
  rope: 'a coil of hemp rope',
  crowbar: 'a crowbar made entirely of dark forged iron (no wooden handle, no colour other than iron grey and a little rust): one curved claw end, one flat chisel end, lying diagonally',
  toolkit: 'a red metal toolbox with a handle, a wrench and a hammer sticking out',
  magnifier: 'a magnifying glass with a brass rim and a wooden handle',
  shovel: 'a spade with a wooden D-handle and an iron blade, upright',
  notebook: 'a leather-bound notebook closed with an elastic band, a pencil beside it',
  map: 'a folded paper map with a dashed route and a red cross on it',
  watch: 'an open brass pocket watch on a short chain',
  backpack: 'a canvas and leather backpack with brass buckles',
  bandages: 'two rolled white bandages and a safety pin',
  'chalk-salt': 'a small cloth sack of salt tied with string, and a stick of white chalk beside it',
  lockpicks: 'a set of lockpicks fanned out of a leather roll',
  binoculars: 'a pair of brass marine binoculars',
  compass: 'a brass pocket compass with a red needle',
  camera: 'a 1920s folding camera with a leather body and a round lens',
  'first-aid-kit': 'a first-aid case in white enamel with a red cross and a leather handle',
  laudanum: 'a small brown glass medicine bottle with a cork and a paper label',
  flask: 'a silver hip flask with a leather band',
  crucifix: 'a brass crucifix',
  amulet: 'an ancient round amulet on a chain, an engraved eye at its centre',
  'old-book': 'an old leather-bound book with a copper clasp and a symbol on its cover',
  // Break-in and escape
  'pocket-knife': 'a folding pocket knife, half open, with a horn handle',
  'chain-padlock': 'a coil of heavy iron chain with a big old padlock hanging on it',
  'hand-drill': 'a hand-cranked drill (brace) with a wooden handle and a steel bit',
  hacksaw: 'a hacksaw with a steel frame and a wooden handle',
  blowtorch: 'a brass blowtorch with a small blue flame at its nozzle',
  'climbing-irons': 'a pair of steel climbing spikes with leather straps, as worn by linemen',
  'block-tackle': 'a wooden pulley block with its rope and an iron hook',
  // Light and survival
  'dark-lantern': 'a dark lantern: a black tin lantern with a sliding shutter half closed over a glowing lens',
  'carbide-lamp': "a miner's brass carbide lamp with a polished reflector and a small white flame",
  searchlight: 'a large portable searchlight on a short stand, its round lens glowing',
  canteen: 'a metal canteen in a canvas cover with a strap',
  tent: 'a small pitched canvas tent with guy ropes',
  blanket: 'a folded grey wool blanket with a red stripe',
  'camp-stove': 'a small brass camping stove with a pot on it',
  'bear-trap': 'an open iron jaw trap with a chain',
  // Medical and danger
  'doctors-bag': "a black leather doctor's bag, open, a stethoscope hanging out",
  'smelling-salts': 'a small corked glass bottle of smelling salts with a paper label',
  morphine: 'a 1920s glass syringe and two small vials of morphine in a metal case',
  straitjacket: 'a canvas straitjacket with leather buckles and long sleeves',
  'gas-mask': 'a 1920s gas mask with round glass eyepieces and a filter canister',
  'diving-suit': 'an old copper diving helmet with round windows, rivets and a hose',
  // Story and curiosities
  keyring: 'a large iron ring holding about ten old keys of different shapes',
  'gin-bottle': 'a clear bottle of bootleg gin with a handwritten label, half full',
  cigarettes: 'an open paper pack of cigarettes with a few sticking out',
  'pocket-mirror': 'a small round pocket mirror in a brass case, open',
  'playing-cards': 'a deck of playing cards fanned out, a few face up',
  banknotes: 'a roll of old banknotes held by a rubber band',
  'forged-papers': 'an identity booklet and a folded document with an official stamp',
  'rabbit-foot': "a lucky rabbit's foot on a small brass chain",
  // Papers the keeper fills in
  letter: 'a folded handwritten letter with its torn envelope and a wax seal',
  telegram: 'a 1920s telegram form with typed paper strips glued on it',
  'newspaper-clipping': 'a yellowed newspaper clipping with a headline and a column, slightly torn',
  'floor-plan': 'a rolled-out architectural floor plan of a house, blue ink on paper, corners curling',
  photograph: 'an old black and white photograph with a white border, slightly bent',
  diary: 'a small leather diary, open, with dense handwriting',
  'asylum-file': 'a thick manila case file tied with string, a typed label on the cover',
  'notary-deed': 'an official deed on heavy paper with a red wax seal and a ribbon',
  // Eldritch artefacts
  'skin-psalter': 'an ancient psalter bound in pale, thin leather, with a corroded metal clasp and wave-like symbols',
  'squatting-idol': 'a small statuette of black stone showing a squatting creature with too many arms',
  'ritual-dagger': 'a ritual dagger with an obsidian blade and a carved bone handle',
  'phonograph-cylinder': 'a wax phonograph cylinder in its cardboard tube',
  'sealed-jar': 'a thick glass jar sealed with wax, something pale floating in murky liquid inside',
  'black-mirror': 'a round polished black obsidian mirror in a simple wooden frame',
  'hag-stone': 'a smooth grey pebble with a natural hole through it, on a cord',
  'strange-key': 'an old key of an iridescent, unknown metal with an odd twisting shape',
  'ceremonial-robe': 'a dark hooded ceremonial robe embroidered with strange symbols, folded',
  'wrong-compass': 'a brass compass whose needle points at something off to the side, the glass cracked',
  // Keys
  'casket-key': 'a tiny ornate brass key for a jewellery box, with a small ribbon',
  'rusty-key': 'a big heavy old iron key covered in rust, with a large round bow',
  'house-key': 'a front door key with a small cardboard label tied to it with string',
  'hotel-key': 'a hotel room key attached to a heavy numbered brass tag',
  'deposit-key': 'a flat double-bitted bank safe-deposit key with a number engraved on it',
  'skeleton-key': 'a slender old skeleton key with its bit filed down to a thin hook',
}
const DEFAULT = ['revolver-38', 'lantern', 'rope', 'first-aid-kit', 'crowbar', 'amulet']

/** The style every card shares, so the comparison is about drawings, not prompts. */
const STYLE = (subject) =>
  `A single object: ${subject}. Centered, filling most of the square frame. Flat vector illustration for a 1920s investigation-horror collectible card game: bold dark ink outlines (#15110a), flat fills in a muted period palette (aged brass #cbbd93, dark wood #8c5b34, iron #3b3429, paper #ece1c4, copper #c9873f, deep red #ac3b2c, leather #5d3f27), a few thin highlight strokes, slight three-quarter view. No text, no letters, no background, no frame, no ground shadow: transparent background. Square viewBox.`

const args = process.argv.slice(2)
const opt = (name, fallback) => {
  const i = args.indexOf(`--${name}`)
  return i >= 0 ? args[i + 1] : fallback
}
const first = args.find((a, i) => !a.startsWith('--') && !args[i - 1]?.startsWith('--'))
// "all": every card with a subject (the whole catalogue); cards already generated are skipped unless --force.
const ids = first === 'all' ? Object.keys(SUBJECTS) : first ? first.split(',') : DEFAULT
for (const id of ids) if (!SUBJECTS[id]) throw new Error(`No subject for "${id}" (${Object.keys(SUBJECTS).join(', ')})`)
const model = opt('model', 'arrow-2')
const force = args.includes('--force')
const out = opt('out', 'decor-review/quiver')
const key = process.env.QUIVERAI_API_KEY
if (!key) throw new Error('Set QUIVERAI_API_KEY')

mkdirSync(out, { recursive: true })
const manifestPath = join(out, 'manifest.json')
const manifest = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : { cards: {} }

let tokens = 0
for (const id of ids) {
  const file = join(out, `${id}.svg`)
  if (!force && existsSync(file) && manifest.cards[id]) {
    console.log(`${id}: already there (--force to regenerate)`)
    continue
  }
  const prompt = STYLE(SUBJECTS[id])
  const res = await fetch('https://api.quiver.ai/v1/svgs/generations', {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model, prompt, n: 1 }),
    signal: AbortSignal.timeout(180_000),
  })
  const body = await res.json().catch(() => null)
  const svg = body?.data?.[0]?.svg
  if (!res.ok || typeof svg !== 'string') {
    console.error(`${id}: failed (${res.status}) ${JSON.stringify(body?.error ?? body).slice(0, 300)}`)
    continue
  }
  writeFileSync(file, svg)
  const sandbox = svg.includes('data-quiverai-sandbox')
  manifest.cards[id] = { model, prompt, usage: body.usage ?? null, sandbox, createdAt: new Date().toISOString() }
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)
  tokens += body.usage?.total_tokens ?? 0
  console.log(`${id}: ${sandbox ? 'SANDBOX placeholder' : 'drawn'} (${body.usage?.output_tokens ?? '?'} output tokens)`)
}
console.log(`Done: ${tokens} tokens this run. Open /dev/items/compare with the dev server running.`)
